if (logItem) {
  const plankName = logItem.name.replace('_log', '_planks');
  const plankData = mcData.itemsByName[plankName];
  if (plankData) {
    const plankRecipe = bot.recipesFor(plankData.id, null, 1, null)[0];
    if (plankRecipe) {
